const b = document.querySelector('button');
a.addEventListener('click', () => console.log('div'));
b.addEventListener('click', (e) => {
  e.stopPropagation();
  console.log('btn');
});

const a = document.createElement('a');
a.href = '#x';
a.textContent = 'lnk';
document.body.append(a);
a.addEventListener('click', (e) => e.preventDefault());

topics.intro:
**Суть.** Замість того, щоб вішати слухач на кожен елемент списку, вішаємо **один** на батька. Через `event.target` визначаємо, куди клікнули. Бонус: нові елементи, додані пізніше, теж працюють без нових слухачів. Шаблон: `parent.addEventListener('click', e => { const item = e.target.closest('.item'); if (!item) return; ... })`.

**Приклад на тему (інші значення, ніж у завданнях):**
```js
list.addEventListener('click', (event) => {
  const btn = event.target.closest('.del');
  if (!btn) return;                 // клікнули не по кнопці
  btn.closest('li').remove();       // видаляємо її li
});
```

tasks.example:
const ul = document.querySelector('ul');
ul.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (!b) return;
  b.closest('li').remove();
});

const ul = document.querySelector('ul');
ul.addEventListener('click', (e) => {
  if (e.target.matches('span')) e.target.classList.toggle('on');
});

const box = document.querySelector('ul');
function update() {
  console.log(box.children.length);
}
box.addEventListener('click', (e) => {
  const b = e.target.closest('button');
  if (b) { b.parentElement.remove(); update(); }
});
update();

topics.intro:
**Суть.** Запис `const { name, age } = user` одним рядком витягує властивості об'єкта в окремі змінні з такими ж назвами. Замість `const name = user.name; const age = user.age;`. Порядок не важливий. Якщо ключа немає, змінна буде `undefined`.

**Приклад на тему (інші значення, ніж у завданнях):**
```js
const user = { name: 'Ол', age: 20, city: 'Київ' };
const { name, age } = user;
console.log(name, age);   // Ол 20
const { country } = user;
console.log(country);     // undefined
```

