console.log(new D({ t: 'a', p: 5, off: 2 }).cheap);

const root = document.querySelector('div');
let list = ['a', 'b'];
function draw() {
  root.innerHTML = '';
  for (const x of list) {
    const p = document.createElement('p');
    p.textContent = x;
    root.append(p);
  }
}
root.addEventListener('click', (e) => {
  const p = e.target.closest('p');
  if (!p) return;
  list = list.filter((x) => x !== p.textContent);
  draw();
});
draw();
